from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence.models import AnalyzeResult

def extract_invoice_fields(payload, config=None):
    config = config or {}
    endpoint = os.environ["AZURE_DOCUMENTINTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENTINTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    def parse_invoice_result(invoices: AnalyzeResult):
        if not invoices.documents:
            return {}

        invoice = invoices.documents[0]
        extracted_data = {}

        vendor_field = invoice.fields.get("VendorName")
        if vendor_field:
            extracted_data["vendor"] = vendor_field.content

        date_field = invoice.fields.get("InvoiceDate")
        if date_field and date_field.value:
            extracted_data["date"] = date_field.value.isoformat()

        total_field = invoice.fields.get("InvoiceTotal")
        if total_field and total_field.value:
            extracted_data["total"] = total_field.value.amount

        line_items = []
        items_field = invoice.fields.get("Items")
        if items_field and items_field.value:
            for item_field in items_field.value:
                item_details = item_field.value
                if not item_details:
                    continue
                line_item = {}

                desc_field = item_details.get("Description")
                if desc_field:
                    line_item["description"] = desc_field.content

                qty_field = item_details.get("Quantity")
                if qty_field and qty_field.value is not None:
                    line_item["quantity"] = qty_field.value

                amount_field = item_details.get("Amount")
                if amount_field and amount_field.value:
                    line_item["amount"] = amount_field.value.amount

                line_items.append(line_item)

        extracted_data["line_items"] = line_items
        return extracted_data
    result = parse_invoice_result(
        document_intelligence_client.begin_analyze_document(
            "prebuilt-invoice", analyze_request=payload, content_type="application/octet-stream"
        ).result()
    )
    return result
